const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);

  // Navigation State
  const [view, setView] = useState<'landing' | 'dashboard'>('landing');

  // Global Language State
  const [language, setLanguage] = useState<'English' | 'Hindi' | 'Bengali'>('English');
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);

  // Access current translations
  const t = translations[language];

  useEffect(() => {
    if (localStorage.getItem('theme') === 'dark' || (!('theme' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDarkMode(true);
    }
  };

  const scrollToBooking = () => {
    const bookingElement = document.getElementById('booking');
    if (bookingElement) {
        bookingElement.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const startNicheAnalysis = (prompt: string) => {
      scrollToBooking();
  };

  const openAuth = (mode: 'signin' | 'signup') => {
    setAuthMode(mode);
    setIsAuthOpen(true);
  };

  const handleAuthSuccess = (user: UserProfile) => {
    setCurrentUser(user);
    if (user.language && (user.language === 'English' || user.language === 'Hindi' || user.language === 'Bengali')) {
        setLanguage(user.language as any);
    }
    if (user.isNewUser) {
      setShowWelcomeModal(true);
    } else {
      setView('dashboard'); // Auto-redirect returning users
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setView('landing');
  };

  const handleLanguageChange = (lang: 'English' | 'Hindi' | 'Bengali') => {
      setLanguage(lang);
      setIsLangMenuOpen(false);
  };

  // If viewing Dashboard, render full screen Dashboard Component
  if (view === 'dashboard' && currentUser) {
      return <Dashboard user={currentUser} onLogout={handleLogout} />;
  }

  return (
    <div className="min-h-screen flex flex-col font-sans text-slate-600 dark:text-slate-300 transition-colors duration-500 bg-gray-50 dark:bg-navy-950">

      {/* Global Noise Texture Overlay */}
      <div className="bg-noise"></div>

      {/* Authentication Modal */}
      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        initialMode={authMode} 
        onAuthSuccess={handleAuthSuccess}
      />

      {/* Welcome Modal for New Users */}
      <WelcomeModal 
        isOpen={showWelcomeModal}
        onClose={() => setShowWelcomeModal(false)}
        onStart={() => {
            setShowWelcomeModal(false);
            setView('dashboard');
        }}
        userName={currentUser?.name || "User"}
      />

      {/* Navbar */}
      <nav className="sticky top-0 z-50 bg-white/80 dark:bg-navy-950/80 backdrop-blur-md border-b border-slate-100 dark:border-slate-800/50 transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-2 sm:gap-3 group cursor-pointer" onClick={() => setView('landing')}>
              <BrandLogo className="w-10 h-10 md:w-11 md:h-11 transition-transform group-hover:scale-105" />
              <div className="flex flex-col">
                  <span className="font-bold text-lg md:text-xl tracking-tight text-navy-900 dark:text-white leading-none">SimpleAgentix</span>
                  <span className="text-[9px] md:text-[10px] uppercase font-bold text-vibrant-orange tracking-widest leading-none mt-1">Automation</span>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-8">
              <a href="#features" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.features}</a>
              <a href="#blogs" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">Blogs</a>
              <a href="#pricing" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.pricing}</a>
              <button onClick={scrollToBooking} className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">Contact</button>
            </div>
            <div className="flex items-center gap-2 md:gap-4">
               {/* Global Language Switcher */}
               <div className="relative">
                   <button 
                       onClick={() => setIsLangMenuOpen(!isLangMenuOpen)}
                       className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors text-xs font-bold"
                   >
                       <Globe className="w-3.5 h-3.5 text-slate-500" />
                       <span className="hidden sm:inline">{language}</span>
                       <span className="sm:hidden">{language.substring(0,2).toUpperCase()}</span>
                       <ChevronDown className="w-3 h-3 text-slate-400" />
                   </button>
                   {isLangMenuOpen && (
