                               <button 
                                   key={l} 
                                   onClick={() => handleLanguageChange(l as any)}
                                   className={`w-full text-left px-4 py-2.5 text-xs font-bold hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors ${language === l ? 'text-vibrant-orange' : 'text-slate-600 dark:text-slate-400'}`}
                               >
                                   {l}
                               </button>
                           ))}
                       </div>
                   )}
               </div>

               <button 
                onClick={toggleTheme}
                className="p-1.5 sm:p-2 rounded-full text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-slate-800 transition-colors"
                aria-label="Toggle Dark Mode"
               >
                 {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
               </button>

               {currentUser ? (
                 <div className="flex items-center gap-3 pl-2 border-l border-slate-200 dark:border-slate-700">
                    <button 
                        onClick={() => setView('dashboard')}
                        className="hidden sm:flex items-center gap-2 px-4 py-2 bg-vibrant-green hover:bg-emerald-500 text-white rounded-lg text-xs font-bold transition-all shadow-md"
                    >
                        Go to Dashboard <ArrowRight className="w-3 h-3" />
