                    <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-full bg-gradient-to-br from-teal-500 to-vibrant-green text-white flex items-center justify-center font-bold shadow-md cursor-pointer" onClick={() => setView('dashboard')}>
                        {currentUser.name.charAt(0)}
                    </div>
                 </div>
               ) : (
                 <>
                   <button 
                    onClick={() => openAuth('signin')}
                    className="hidden md:block text-sm font-medium text-navy-900 dark:text-white hover:text-navy-700 dark:hover:text-slate-200"
                   >
                     {t.nav.signin}
                   </button>
