                        <button 
                            type="button"
                            onClick={() => {
                                setMode(mode === 'signin' ? 'signup' : 'signin');
                                setEmailError('');
                            }}
                            className="ml-1 text-vibrant-orange font-bold hover:underline"
                        >
                            {mode === 'signin' ? "Sign up free" : "Log in"}
                        </button>
                     </p>
                  </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

